namespace scratchbird::engine::sblr { namespace { void p(std::vector<uint8_t>&o,uint64_t v,size_t n){for(size_t i=0;i<n;i++)o.push_back(uint8_t(v>>(8*i)));} uint64_t g(const uint8_t*b,size_t n){uint64_t v=0;for(size_t i=0;i<n;i++)v|=uint64_t(b[i])<<(8*i);return v;} template<class T>bool nz(const T&x){return std::any_of(x.begin(),x.end(),[](auto v){return v!=0;});} std::vector<uint8_t> h(const char*m,size_t n){std::vector<uint8_t>o(m,m+4);p(o,1,2);p(o,n,2);p(o,n,4);p(o,0,4);return o;} bool vh(const uint8_t*b,size_t n,const char*m,size_t z){return b&&n==z&&std::equal(b,b+4,m)&&g(b+4,2)==1&&g(b+6,2)==z&&g(b+8,4)==z&&std::all_of(b+12,b+16,[](auto v){return v==0;});} WindowSha sha(const char*d,const uint8_t*b,size_t n){std::vector<uint8_t>x(d,d+strlen(d));x.insert(x.end(),b,b+n);return scratchbird::core::hash::ComputeSha256Digest(x).digest;} }
std::vector<uint8_t> EncodeSblrWindowRequestV1(const SblrWindowRequestV1&v){if(!nz(v.receipt)||!v.occurrence||!v.window_occurrence)return{};auto o=h("WIRQ",64);o.insert(o.end(),v.receipt.begin(),v.receipt.end());p(o,v.occurrence,8);p(o,v.window_occurrence,4);o.insert(o.end(),20,0);return o;} bool DecodeSblrWindowRequestV1(const uint8_t*b,size_t n,SblrWindowRequestV1*out,std::string*d){if(!out||!vh(b,n,"WIRQ",64)||std::any_of(b+44,b+64,[](auto v){return v;})){if(d)*d="WIRQ invalid";return false;} SblrWindowRequestV1 v;std::copy_n(b+16,16,v.receipt.begin());v.occurrence=g(b+32,8);v.window_occurrence=g(b+40,4);if(EncodeSblrWindowRequestV1(v).empty())return false;*out=v;return true;}
std::vector<uint8_t> EncodeSblrWindowDescriptorV1(const SblrWindowDescriptorV1&v,bool op){if(!nz(v.body)||!v.availability)return{};auto o=h(op?"WIDO":"WIDD",488);o.insert(o.end(),v.body.begin(),v.body.end());auto e=sha("ScratchBird.SblrWindowDescriptor.V1",o.data()+16,392);if(nz(v.evidence)&&e!=v.evidence)return{};o.insert(o.end(),e.begin(),e.end());p(o,v.availability,8);o.insert(o.end(),40,0);return o;} bool DecodeSblrWindowDescriptorV1(const uint8_t*b,size_t n,SblrWindowDescriptorV1*out,std::string*d,bool op){if(!out||!vh(b,n,op?"WIDO":"WIDD",488)||std::any_of(b+448,b+488,[](auto v){return v;})){if(d)*d="WID invalid";return false;} SblrWindowDescriptorV1 v;std::copy_n(b+16,392,v.body.begin());std::copy_n(b+408,32,v.evidence.begin());v.availability=g(b+440,8);if(EncodeSblrWindowDescriptorV1(v,op).empty())return false;*out=v;return true;}
std::vector<uint8_t> EncodeSblrWindowResultV1(const SblrWindowResultV1&v){if(!nz(v.body)||v.body[24]!=1||v.body[25]>1||!g(v.body.data()+56,4)||!v.availability||!nz(v.publication_barrier))return{};auto o=h("WIRS",320);o.insert(o.end(),v.body.begin(),v.body.end());auto e=sha("ScratchBird.SblrWindowExecutorEvidence.V1",o.data()+16,240);if(nz(v.evidence)&&e!=v.evidence)return{};o.insert(o.end(),e.begin(),e.end());p(o,v.availability,8);o.insert(o.end(),v.publication_barrier.begin(),v.publication_barrier.end());o.insert(o.end(),8,0);return o;} bool DecodeSblrWindowResultV1(const uint8_t*b,size_t n,SblrWindowResultV1*out,std::string*d){if(!out||!vh(b,n,"WIRS",320)||std::any_of(b+312,b+320,[](auto v){return v;})){if(d)*d="WIRS invalid";return false;} SblrWindowResultV1 v;std::copy_n(b+16,240,v.body.begin());std::copy_n(b+256,32,v.evidence.begin());v.availability=g(b+288,8);std::copy_n(b+296,16,v.publication_barrier.begin());if(EncodeSblrWindowResultV1(v).empty())return false;*out=v;return true;}}
